PRAGMA foreign_keys=ON;
CREATE TABLE levels(code TEXT PRIMARY KEY, sequence INTEGER UNIQUE NOT NULL, weeks INTEGER NOT NULL, outcome TEXT NOT NULL);
CREATE TABLE units(id INTEGER PRIMARY KEY, level_code TEXT NOT NULL REFERENCES levels(code), sequence INTEGER UNIQUE NOT NULL, title TEXT NOT NULL, explanation TEXT NOT NULL);
CREATE TABLE lessons(id INTEGER PRIMARY KEY, unit_id INTEGER NOT NULL REFERENCES units(id), day_number INTEGER UNIQUE NOT NULL, day_in_unit INTEGER NOT NULL CHECK(day_in_unit BETWEEN 1 AND 7), kind TEXT NOT NULL CHECK(kind IN ('learn','review')), title TEXT NOT NULL, objective TEXT NOT NULL, estimated_minutes INTEGER NOT NULL, example_fr TEXT, example_en TEXT, UNIQUE(unit_id,day_in_unit));
CREATE TABLE lesson_blocks(id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL REFERENCES lessons(id), position INTEGER NOT NULL, block_type TEXT NOT NULL CHECK(block_type IN ('explanation','example','production','review')), content_json TEXT NOT NULL CHECK(json_valid(content_json)), UNIQUE(lesson_id,position));
CREATE TABLE grammar_topics(id INTEGER PRIMARY KEY, unit_id INTEGER NOT NULL REFERENCES units(id), topic TEXT NOT NULL, note TEXT NOT NULL, example_fr TEXT NOT NULL, example_en TEXT NOT NULL);
CREATE TABLE lesson_grammar(lesson_id INTEGER NOT NULL REFERENCES lessons(id), grammar_topic_id INTEGER NOT NULL REFERENCES grammar_topics(id), PRIMARY KEY(lesson_id,grammar_topic_id));
CREATE TABLE lexemes(id INTEGER PRIMARY KEY, french TEXT NOT NULL, english TEXT NOT NULL, part_of_speech TEXT NOT NULL, gender TEXT CHECK(gender IN ('m','f') OR gender IS NULL), level_code TEXT NOT NULL REFERENCES levels(code), ipa TEXT, notes TEXT, UNIQUE(french,part_of_speech));
CREATE TABLE conversation_words(rank INTEGER PRIMARY KEY CHECK(rank BETWEEN 1 AND 3000), lexeme_id INTEGER NOT NULL UNIQUE REFERENCES lexemes(id), french TEXT NOT NULL UNIQUE, meaning_en TEXT NOT NULL, ipa TEXT NOT NULL, example_fr TEXT NOT NULL, example_en TEXT NOT NULL, example_status TEXT NOT NULL CHECK(example_status IN ('reviewed','draft','corpus_unreviewed','authored_unreviewed')), example_source TEXT, verb_id INTEGER REFERENCES verbs(id), conjugation_status TEXT NOT NULL CHECK(conjugation_status IN ('available','pending_review','not_applicable')), introduced_day INTEGER NOT NULL REFERENCES lessons(day_number));
CREATE TABLE lesson_lexemes(lesson_id INTEGER NOT NULL REFERENCES lessons(id), lexeme_id INTEGER NOT NULL REFERENCES lexemes(id), PRIMARY KEY(lesson_id,lexeme_id));
CREATE TABLE alphabet(letter TEXT PRIMARY KEY, letter_name_fr TEXT NOT NULL, ipa TEXT NOT NULL, example TEXT NOT NULL);
CREATE TABLE sound_patterns(id INTEGER PRIMARY KEY, spelling TEXT NOT NULL, ipa TEXT NOT NULL, example TEXT NOT NULL, note TEXT NOT NULL);
CREATE TABLE pronunciation_items(id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL REFERENCES lessons(id), position INTEGER NOT NULL, category TEXT NOT NULL, grapheme TEXT NOT NULL, ipa TEXT NOT NULL, example_fr TEXT NOT NULL, example_ipa TEXT NOT NULL, meaning_en TEXT NOT NULL, articulation TEXT NOT NULL, contrast TEXT, UNIQUE(lesson_id,position));
CREATE INDEX idx_pronunciation_lesson ON pronunciation_items(lesson_id,position);
CREATE TABLE content_sources(id INTEGER PRIMARY KEY, source_url TEXT UNIQUE NOT NULL, title TEXT NOT NULL, usage_note TEXT NOT NULL);
CREATE TABLE numbers(value INTEGER PRIMARY KEY, french TEXT NOT NULL, english TEXT NOT NULL);
CREATE TABLE verbs(id INTEGER PRIMARY KEY, infinitive TEXT UNIQUE NOT NULL, english TEXT NOT NULL, group_name TEXT NOT NULL, auxiliary TEXT NOT NULL CHECK(auxiliary IN ('avoir','être')), level_code TEXT NOT NULL REFERENCES levels(code));
CREATE TABLE conjugations(verb_id INTEGER NOT NULL REFERENCES verbs(id), mood TEXT NOT NULL, tense TEXT NOT NULL, person TEXT NOT NULL, form TEXT NOT NULL, PRIMARY KEY(verb_id,mood,tense,person));
CREATE TABLE flashcards(id INTEGER PRIMARY KEY, lesson_id INTEGER REFERENCES lessons(id), lexeme_id INTEGER REFERENCES lexemes(id), front TEXT NOT NULL, back TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('fr_en','en_fr')), tags_json TEXT NOT NULL CHECK(json_valid(tags_json)));
CREATE TABLE exercises(id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL REFERENCES lessons(id), kind TEXT NOT NULL CHECK(kind IN ('choice','cloze','production')), prompt TEXT NOT NULL, answer TEXT, explanation TEXT, auto_gradable INTEGER NOT NULL CHECK(auto_gradable IN (0,1)), position INTEGER NOT NULL, UNIQUE(lesson_id,position));
CREATE TABLE exercise_choices(exercise_id INTEGER NOT NULL REFERENCES exercises(id), position INTEGER NOT NULL, choice_text TEXT NOT NULL, correct INTEGER NOT NULL CHECK(correct IN (0,1)), PRIMARY KEY(exercise_id,position));
CREATE TABLE lesson_prerequisites(lesson_id INTEGER NOT NULL REFERENCES lessons(id), prerequisite_lesson_id INTEGER NOT NULL REFERENCES lessons(id), PRIMARY KEY(lesson_id,prerequisite_lesson_id), CHECK(lesson_id!=prerequisite_lesson_id));
CREATE TABLE media_assets(id INTEGER PRIMARY KEY, lesson_id INTEGER REFERENCES lessons(id), asset_type TEXT NOT NULL CHECK(asset_type IN ('audio','image','transcript')), locale TEXT, uri TEXT NOT NULL, transcript TEXT, status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','ready')));
CREATE TABLE learners(id INTEGER PRIMARY KEY, external_auth_id TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, preferred_locale TEXT NOT NULL DEFAULT 'en', current_day INTEGER NOT NULL DEFAULT 1);
CREATE TABLE lesson_progress(learner_id INTEGER NOT NULL REFERENCES learners(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), state TEXT NOT NULL CHECK(state IN ('available','started','completed')), best_score REAL CHECK(best_score BETWEEN 0 AND 1), completed_at TEXT, PRIMARY KEY(learner_id,lesson_id));
CREATE TABLE attempts(id INTEGER PRIMARY KEY, learner_id INTEGER NOT NULL REFERENCES learners(id), exercise_id INTEGER NOT NULL REFERENCES exercises(id), response TEXT NOT NULL, is_correct INTEGER, submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE flashcard_reviews(learner_id INTEGER NOT NULL REFERENCES learners(id), flashcard_id INTEGER NOT NULL REFERENCES flashcards(id), stability REAL NOT NULL DEFAULT 0, difficulty REAL NOT NULL DEFAULT 0, interval_days INTEGER NOT NULL DEFAULT 0, due_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_rating INTEGER CHECK(last_rating BETWEEN 1 AND 4), reviewed_at TEXT, PRIMARY KEY(learner_id,flashcard_id));
CREATE INDEX idx_lessons_unit ON lessons(unit_id,day_in_unit);
CREATE INDEX idx_exercises_lesson ON exercises(lesson_id);
CREATE INDEX idx_cards_lesson ON flashcards(lesson_id);
CREATE INDEX idx_reviews_due ON flashcard_reviews(learner_id,due_at);
CREATE VIEW daily_course AS SELECT l.day_number,lv.code AS level,u.title AS unit_title,l.kind,l.title,l.objective,l.estimated_minutes,l.example_fr,l.example_en FROM lessons l JOIN units u ON u.id=l.unit_id JOIN levels lv ON lv.code=u.level_code ORDER BY l.day_number;
CREATE TABLE IF NOT EXISTS reference_notes(id INTEGER PRIMARY KEY, level_code TEXT NOT NULL REFERENCES levels(code), category TEXT NOT NULL, title TEXT NOT NULL, explanation TEXT NOT NULL, example_fr TEXT NOT NULL, example_en TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reference_category ON reference_notes(category,level_code);
CREATE TABLE IF NOT EXISTS voice_integrations(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, repository_url TEXT NOT NULL, pinned_commit TEXT NOT NULL, capability TEXT NOT NULL, integration_status TEXT NOT NULL CHECK(integration_status IN ('candidate','validated','active')), french_verified INTEGER NOT NULL DEFAULT 0 CHECK(french_verified IN (0,1)), notes TEXT NOT NULL);

-- Morphology reference is derived from Lefff 3.4 (LGPL-LR); see THIRD_PARTY_DATA.md.
CREATE TABLE lexical_grammar(lexeme_id INTEGER PRIMARY KEY REFERENCES lexemes(id), lemmas_json TEXT NOT NULL CHECK(json_valid(lemmas_json)), parts_of_speech_json TEXT NOT NULL CHECK(json_valid(parts_of_speech_json)), genders_json TEXT NOT NULL CHECK(json_valid(genders_json)), usage_note TEXT NOT NULL, source_url TEXT NOT NULL);
CREATE TABLE lexical_inflections(lexeme_id INTEGER NOT NULL REFERENCES lexemes(id), form TEXT NOT NULL, features TEXT NOT NULL, ipa TEXT, PRIMARY KEY(lexeme_id,form,features));
CREATE TABLE verb_reference(verb_id INTEGER PRIMARY KEY REFERENCES verbs(id), infinitive_ipa TEXT, impersonal INTEGER NOT NULL CHECK(impersonal IN (0,1)), auxiliary_note TEXT NOT NULL, agreement_note TEXT NOT NULL, usage_note TEXT NOT NULL, source_url TEXT NOT NULL);
CREATE TABLE verb_participles(verb_id INTEGER NOT NULL REFERENCES verbs(id), kind TEXT NOT NULL, agreement TEXT NOT NULL, form TEXT NOT NULL, ipa TEXT, PRIMARY KEY(verb_id,kind,agreement,form));
CREATE TABLE conjugation_variants(verb_id INTEGER NOT NULL REFERENCES verbs(id), mood TEXT NOT NULL, tense TEXT NOT NULL, person TEXT NOT NULL, form TEXT NOT NULL, ipa TEXT, note TEXT NOT NULL, PRIMARY KEY(verb_id,mood,tense,person,form));
CREATE TABLE conjugation_pronunciations(verb_id INTEGER NOT NULL, mood TEXT NOT NULL, tense TEXT NOT NULL, person TEXT NOT NULL, ipa TEXT, word_parts_json TEXT NOT NULL CHECK(json_valid(word_parts_json)), status TEXT NOT NULL CHECK(status IN ('dictionary','word_parts','not_supplied')), note TEXT NOT NULL, PRIMARY KEY(verb_id,mood,tense,person), FOREIGN KEY(verb_id,mood,tense,person) REFERENCES conjugations(verb_id,mood,tense,person));
CREATE TABLE conjugation_coverage(verb_id INTEGER NOT NULL REFERENCES verbs(id), mood TEXT NOT NULL, tense TEXT NOT NULL, expected_persons_json TEXT NOT NULL CHECK(json_valid(expected_persons_json)), available_persons_json TEXT NOT NULL CHECK(json_valid(available_persons_json)), status TEXT NOT NULL CHECK(status IN ('complete','source_gap')), PRIMARY KEY(verb_id,mood,tense));
CREATE TABLE phoneme_guides(symbol TEXT PRIMARY KEY, title TEXT NOT NULL, articulation TEXT NOT NULL, example_fr TEXT NOT NULL, example_ipa TEXT NOT NULL, contrast TEXT NOT NULL);
CREATE TABLE pronunciation_rules(id TEXT PRIMARY KEY, level_code TEXT NOT NULL REFERENCES levels(code), title TEXT NOT NULL, explanation TEXT NOT NULL, example_fr TEXT NOT NULL, example_ipa TEXT NOT NULL, introduced_day INTEGER NOT NULL REFERENCES lessons(day_number));
CREATE TABLE vocabulary_pronunciation(lexeme_id INTEGER PRIMARY KEY REFERENCES lexemes(id), phonemes_json TEXT NOT NULL CHECK(json_valid(phonemes_json)), note TEXT NOT NULL, audio_status TEXT NOT NULL DEFAULT 'not_recorded');
CREATE TABLE sentence_patterns(id INTEGER PRIMARY KEY, level_code TEXT NOT NULL REFERENCES levels(code), title TEXT NOT NULL, pattern TEXT NOT NULL, explanation TEXT NOT NULL, components_json TEXT NOT NULL CHECK(json_valid(components_json)), example_fr TEXT NOT NULL, example_en TEXT NOT NULL, common_error TEXT NOT NULL, introduced_day INTEGER NOT NULL REFERENCES lessons(day_number));
CREATE TABLE sentence_pattern_words(pattern_id INTEGER NOT NULL REFERENCES sentence_patterns(id), lexeme_id INTEGER NOT NULL REFERENCES lexemes(id), link_type TEXT NOT NULL, PRIMARY KEY(pattern_id,lexeme_id));
CREATE TABLE sentence_tasks(id INTEGER PRIMARY KEY, pattern_id INTEGER NOT NULL REFERENCES sentence_patterns(id), kind TEXT NOT NULL CHECK(kind IN ('word_order','translation')), prompt TEXT NOT NULL, tokens_json TEXT NOT NULL CHECK(json_valid(tokens_json)), accepted_answers_json TEXT NOT NULL CHECK(json_valid(accepted_answers_json)), explanation TEXT NOT NULL, auto_gradable INTEGER NOT NULL CHECK(auto_gradable IN (0,1)));
CREATE INDEX idx_sentence_patterns_day ON sentence_patterns(introduced_day);
CREATE INDEX idx_lexical_inflections_word ON lexical_inflections(lexeme_id);
CREATE TABLE pronominal_verbs(id INTEGER PRIMARY KEY, lemma TEXT NOT NULL UNIQUE, base_verb_id INTEGER NOT NULL REFERENCES verbs(id), meaning_en TEXT NOT NULL, usage_note TEXT NOT NULL);
CREATE TABLE pronominal_conjugations(pronominal_verb_id INTEGER NOT NULL REFERENCES pronominal_verbs(id), mood TEXT NOT NULL, tense TEXT NOT NULL, person TEXT NOT NULL, form TEXT NOT NULL, variants_json TEXT NOT NULL CHECK(json_valid(variants_json)), note TEXT NOT NULL, PRIMARY KEY(pronominal_verb_id,mood,tense,person));
